jstrain/quiz-03-arrays-objects/q41.snippet:
function merge(a, b) {
  const out = { ...a };
  for (const [k, v] of Object.entries(b)) {
    out[k] = v && typeof v === 'object' ? merge(out[k] ?? {}, v) : v;
  }
  return out;
}
console.log(merge({ tags: ['a', 'b'] }, { tags: ['z'] }));
console.log(merge({ a: { b: 1 } }, { a: { c: 2 } }));
